from pathlib import Path
from shutil import copy2
from docx import Document
from docx.shared import Pt, Cm
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml.ns import qn

root=Path('docs/report')
src=root/'Ульянкин_ВИ_ИКБО-30-24_Учебная_практика_этап4_рынок.docx'
dst=root/'Ульянкин_ВИ_ИКБО-30-24_Учебная_практика_этап4_образование.docx'
copy2(src,root/'backups/этап4_перед_этапом9.docx')
d=Document(src);anchor=next(p for p in d.paragraphs if p.text.strip()=='СПИСОК ЛИТЕРАТУРЫ')
def font(run):
    run.font.name='Times New Roman';run.font.size=Pt(14)
    for a in ('ascii','hAnsi','cs','eastAsia'):run._element.get_or_add_rPr().get_or_add_rFonts().set(qn('w:'+a),'Times New Roman')
def insert(text,heading=False):
    p=d.add_paragraph(text,style='Heading 2' if heading else None);anchor._p.addprevious(p._p)
    p.paragraph_format.line_spacing=1.5;p.paragraph_format.space_before=Pt(0);p.paragraph_format.space_after=Pt(0)
    p.paragraph_format.first_line_indent=Cm(0 if heading else 1.25);p.paragraph_format.keep_with_next=heading
    p.alignment=WD_ALIGN_PARAGRAPH.LEFT if heading else WD_ALIGN_PARAGRAPH.JUSTIFY
    for r in p.runs:font(r)
    return p
insert('4.5 Образовательные возможности',True)
insert('Дополнительное образование позволяет точечно восполнить пробелы, выявленные при анализе вакансий. Курс «Разработка на Spring» Яндекс Практикума охватывает Spring Boot, REST API и безопасность; в программу входят практические работы над приложением и веб-сервисом [21]. Он может помочь перейти от учебной доменной логики к серверному приложению. Перед выбором курса необходимо отдельно проверить стоимость, даты и требования к подготовке; прохождение программы в настоящей работе не заявляется.')
insert('Материалы курса «Язык SQL» компании Postgres Professional рассматривают PostgreSQL, запросы, транзакции и основы оптимизации [22]. Их целесообразно использовать при переходе от логической ER-модели к физической схеме базы данных VR-арены, создании ограничений и проверке запросов на учебных данных.')
insert('Магистратура даёт возможность углубить системную подготовку. В правилах приёма РТУ МИРЭА на 2026/2027 учебный год по направлению 09.04.04 «Программная инженерия» указан профиль «Архитектура информационных систем» [23]. Он соответствует интересу к проектированию информационных систем и может стать продолжением моделирования и разработки проекта VR-арены; конкретный учебный план и условия приёма необходимо проверить для года поступления.')
insert('В НИУ ВШЭ магистерская программа «Системная и программная инженерия» относится к направлению 09.04.04; в её образовательных результатах указаны проектирование, тестирование и сопровождение сложных и распределённых приложений [24]. В Университете ИТМО программа «Системное и прикладное программное обеспечение» того же направления ориентирована на системную разработку, архитектуру высокопроизводительных и распределённых систем [25]. Обе программы подходят для углубления инженерной подготовки; вторая особенно связана с последующим изучением инфраструктуры и масштабирования.')
insert('Аспирантура ориентирована на исследовательскую работу. В перечне программ аспирантуры НИУ ВШЭ указана научная специальность 2.3.5 «Математическое и программное обеспечение вычислительных систем, комплексов и компьютерных сетей» [26]. Она может быть связана с исследованием средств разработки и архитектуры вычислительных систем. Наличие специальности в перечне вуза не означает автоматического соответствия любой теме диссертации: направление исследования и условия приёма необходимо согласовывать отдельно.')
insert('4.6 Профессиональная траектория',True)
insert('Ближайшая цель — получить опыт работы в роли junior Java backend-разработчика. Для этого необходимо закрепить Java и объектное проектирование на текущем модуле, самостоятельно объяснять решения и тесты и последовательно освоить Spring Boot, REST API и работу с реляционной базой данных. Затем следует расширять практику интеграционного тестирования, Git, Docker и процессов сборки.')
insert('На следующей контрольной точке практики, посвящённой физической модели данных, предлагается преобразовать ER-модель VR-арены в схему PostgreSQL: определить таблицы, ключи и ограничения, подготовить проверочные данные и SQL-запросы. После этого можно изучить подключение приложения через Spring Data JPA и разработать небольшой REST-интерфейс. Это план дальнейшей работы; указанные компоненты в текущем модуле не реализованы.')
insert('Для роста до middle необходимо накопить опыт сопровождения серверных приложений, анализа ошибок, проектирования интеграций, транзакций и производительности, а также изучить брокеры сообщений и CI/CD. На данном этапе приоритетом остаются практическая разработка и дополнительное обучение. Магистратура рассматривается как возможный способ углубить инженерную подготовку, а аспирантура — как последующий вариант при появлении устойчивого исследовательского интереса; решения о поступлении пока нет.')
appendix=next(p for p in d.paragraphs if p.text.strip()=='Приложение А')
refs=[
'21. Разработка на Spring [Электронный ресурс] // Яндекс Практикум. URL: https://practicum.yandex.ru/spring-development/ (дата обращения: 24.11.2026).',
'22. Язык SQL [Электронный ресурс] // Postgres Professional. URL: https://postgrespro.ru/education/university/sqlprimer (дата обращения: 24.11.2026).',
'23. Правила приёма на обучение по образовательным программам бакалавриата, специалитета и магистратуры на 2026/2027 учебный год [Электронный ресурс] // РТУ МИРЭА. URL: https://stavropol.mirea.ru/wp-content/docs/sveden/document/Pravila-priyema-BSM-May-2026.pdf (дата обращения: 24.11.2026).',
'24. Системная и программная инженерия: паспорт образовательной программы [Электронный ресурс] // НИУ ВШЭ. URL: https://www.hse.ru/ma/se/passport (дата обращения: 24.11.2026).',
'25. Системное и прикладное программное обеспечение: программа магистратуры [Электронный ресурс] // Университет ИТМО. URL: https://abit.itmo.ru/program/master/system_software (дата обращения: 24.11.2026).',
'26. Перечень научных специальностей по подготовке научных и научно-педагогических кадров в аспирантуре [Электронный ресурс] // НИУ ВШЭ. URL: https://aspirantura.hse.ru/spec/ (дата обращения: 24.11.2026).']
for text in refs:
    p=d.add_paragraph(text);appendix._p.addprevious(p._p);p.paragraph_format.line_spacing=1.5
    p.paragraph_format.space_before=Pt(0);p.paragraph_format.space_after=Pt(0);p.paragraph_format.first_line_indent=Cm(1.25)
    p.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
    for r in p.runs:font(r)
d.save(dst);check=Document(dst)
assert any(p.text.startswith('4.6 Профессиональная') for p in check.paragraphs)
assert all(any(p.text.startswith(str(n)+'. ') for p in check.paragraphs) for n in range(21,27))
print('Saved',dst)
